#!/usr/bin/env python3
"""Single source for both C4 Markdown formats; generated by render.py."""
import sys
from html import escape
from textwrap import wrap
from canvas import Canvas

TITLE = 'System Context'
BOUNDARY = 'Mansio'
NODES = [('developer',
  'App developer',
  'Person',
  'app/; sdk/',
  'Declares schemas and Effect handlers; the handlers run in the SDK',
  False),
 ('caller', 'Application caller', 'Person', 'sdk/client.ts', 'Players and authenticated tenant users', False),
 ('operator',
  'Operator',
  'Person',
  'server/cmd/mansioctl; server/cmd/dbtool',
  'Tenants, keys, placement, backups; reads the request log and metrics',
  False),
 ('db',
  'Mansio',
  'Software system',
  'server/ (Go)',
  'agentd, controld, edge; one SQLite database per (tenant, app); IR over HTTP',
  True),
 ('objects',
  'Object storage',
  'External system',
  'S3 (SeaweedFS in dev)',
  'SQLite generations and manifests (durable mode)',
  False),
 ('k6',
  'k6 load generator',
  'External system',
  'perf/*.js',
  'IR load over /v1/ops; raw metric points',
  False)]
EDGES = [('developer', 'db', 'Registered schema JSON; handlers stay in the app (TypeScript SDK)'),
 ('caller', 'db', 'IR over HTTP (/v1/resolve, /v1/ops); tickets, API keys or sessions; X-Trace-Id'),
 ('operator', 'db', 'Admin HTTP and CLIs; tenants, keys, moves, backups; request log (JSONL) and /metrics'),
 ('db', 'objects', 'S3 HTTP; write-back of SQLite generations, restore'),
 ('k6', 'db', 'IR scenarios over /v1/ops and trace headers')]
NOTES = 'Since IR-6 the server is the Go server in server/; the Deno platform was deleted (ADR 0013). App handlers\nrun in the client SDK and reach the server as IR requests (ir/spec/v1.md); no application SQL crosses the\nclient boundary. Tenant identity comes from tickets, API keys or sessions (ADR 0012); Postgres is inside the\nsystem, shown at Level 2. No external identity provider is wired. The request log and the metrics are\nfor the deployment\'s own log collector and Prometheus, which are not part of mansio (ADR 0014).'
NAME = 'c4-context-document-db'


def picture():
    cv = Canvas(width=72, height=260)
    row = 2
    for inside in (True, False):
        group = [n for n in NODES if n[5] == inside]
        if not inside:
            cv.frame(0, 0, row, 71, BOUNDARY)
            row += 2
        for offset in range(0, len(group), 2):
            bottoms = []
            for col, (_, title, kind, path, detail, _) in enumerate(group[offset:offset+2]):
                lines = [part for line in [title, '[' + kind + ']', path, detail]
                         for part in wrap(line, 28, break_on_hyphens=False)]
                bottoms.append(cv.box(row, 3 + col*35, 32, lines))
            row = max(bottoms) + 2
    return cv.render()


def mermaid():
    lines = ['flowchart TB', '    subgraph platform["' + BOUNDARY + '"]']
    for inside in (True, False):
        for id, title, kind, path, detail, within in NODES:
            if within == inside:
                label = '<br/>'.join(escape(s, quote=True) for s in [title, '['+kind+']', path, detail])
                lines.append('        ' + id + '["' + label + '"]')
        if inside:
            lines.append('    end')
    for i, (a, b, label) in enumerate(EDGES, 1):
        lines.append(f'    {a} -->|"({i}) {label}"| {b}')
    lines += ['    classDef planned stroke-dasharray: 5 3',
              '    classDef person fill:#fff,stroke-width:2px',
              '    classDef external fill:#f4f4f4']
    for id, _, kind, _, _, inside in NODES:
        if kind == 'Person':
            lines.append(f'    class {id} person')
        elif not inside:
            lines.append(f'    class {id} external')
    return '\n'.join(lines)


def document(github):
    text = '# ' + TITLE + '\n\nRedrawn for IR-6 (ADR 0013) on 2026-11-06 on `ir/06-cutover` from main `7cf4ba6`: the Deno platform is gone and\nthe server is the Go server in `server/`. Both formats are generated from\n'
    text += '`diagrams/' + NAME + '.py`; numbered relationships are identical. All boxes describe landed code.\n\n'
    if github:
        text += '```mermaid\n' + mermaid() + '\n```\n'
    else:
        text += '<!-- c4-render: diagrams/' + NAME + '.py -->\n\n```text\n' + picture() + '\n```\n'
    names = {n[0]: n[1] for n in NODES}
    text += '\n## Relationships\n\n| # | From | To | Relationship |\n| - | --- | --- | --- |\n'
    for i, (a,b,label) in enumerate(EDGES,1):
        text += f'| {i} | {names[a]} | {names[b]} | {label} |\n'
    return text + '\n## Runtime notes\n\n' + NOTES + '\n'


if __name__ == '__main__':
    if '--github' in sys.argv:
        print(document(True), end='')
    elif '--terminal' in sys.argv:
        print(document(False), end='')
    else:
        print(picture())
